export type MessageHandler<I, O> = (payload: I, ctx: MessageContext) => Promise<O>;

export async function activate<I, O>(
  input: AsyncIterable<Envelope>, handle: MessageHandler<I, O>, out: Outbound,
): Promise<void> {
  for await (const env of input) {
    const payload = validate<I>(env.payload, env.type);   // never trust the annotation
    await out.send({ correlationId: env.correlationId, payload: await handle(payload, ctxOf(env)) });
  }
}

