@Controller()
export class OrdersController {
  constructor(private readonly orders: OrderService) {}

  @MessagePattern({ cmd: 'place' })          // reply = return value
  place(order: Order): Promise<Receipt> {
    return this.orders.place(order);         // ordinary injected service
  }
}
